7	/** Configuration options for RedactorService initialization. */
8	export interface RedactorServiceOptions {
9	  /** Optional options passed to MaskerMini.load(...) (offline directory or cacheRoot). */
10	  loadOptions?: MaskerLoadOptions;
11	  /** Optional pre-instantiated or mock NER engine (useful for unit testing). */
12	  redactInstance?: NerEngine;
13	}
