15	/** Escapes special regular expression characters in a string. */
16	function escapeRegex(str: string): string {
17	  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
18	}
19	
20	/**
21	 * Constructs a safe regex matching discrete word occurrences of an entity,
22	 * respecting Unicode word boundaries to prevent substring mutilation of regular words
23	 * (e.g. preventing 'Dan' from matching inside 'Danger' or 'Rob' inside 'problem').
24	 */
25	function createEntityWordBoundaryRegex(original: string): RegExp {
26	  const escaped = escapeRegex(original);
27	  const leading = /^\w/.test(original)
28	    ? "\\b"
29	    : /^[\p{L}\p{N}_]/u.test(original)
30	      ? "(?<![\\p{L}\\p{N}_])"
31	      : "(?<!\\S)";
32	  const trailing = /\w$/.test(original)
33	    ? "\\b"
34	    : /[\p{L}\p{N}_]$/u.test(original)
35	      ? "(?![\\p{L}\\p{N}_])"
36	      : "(?!\\S)";
37	  const flags =
38	    /[\p{L}\p{N}]/u.test(original) && !/^[\x00-\x7F]+$/.test(original)
39	      ? "gu"
40	      : "g";
41	  return new RegExp(`${leading}${escaped}${trailing}`, flags);
42	}
