52	export class RedactorService {
53	  private rules: Map<string, PiiRule>;
54	  private config: RedactorConfig;
55	  private loadOptions?: MaskerLoadOptions;
56	  private instance: NerEngine | null = null;
57	  private initPromise: Promise<NerEngine> | null = null;
58	  private vault: PiiVault = new PiiVault();
59	  private cache: Map<string, CachedResult> = new Map();
60	  private cacheSig = "";
61	
62	  constructor(
63	    customRules: PiiRule[] = [],
64	    initialConfig?: Partial<RedactorConfig>,
65	    options?: RedactorServiceOptions | MaskerLoadOptions
66	  ) {
67	    this.rules = new Map();
68	    for (const rule of [...defaultRules, ...customRules]) {
69	      this.rules.set(rule.id, { ...rule });
70	    }
71	
72	    this.config = {
73	      enabled: true,
74	      maskUserInputs: true,
75	      maskToolResults: true,
76	      maskContextMessages: true,
77	      notifyOnRedact: true,
78	      minimumConfidence: 0.55,
79	      ...initialConfig,
80	    };
81	
82	    if (options) {
83	      if ("redactInstance" in options || "loadOptions" in options) {
84	        const svcOpts = options as RedactorServiceOptions;
85	        this.loadOptions = svcOpts.loadOptions;
86	        if (svcOpts.redactInstance) {
87	          this.instance = svcOpts.redactInstance;
88	        }
89	      } else {
90	        this.loadOptions = options as MaskerLoadOptions;
91	      }
92	    }
93	  }
94	
95	  /** Returns whether redaction is globally enabled. */
96	  public isEnabled(): boolean {
97	    return this.config.enabled;
98	  }
99	
100	  /** Globally enable or disable redaction. */
101	  public setEnabled(enabled: boolean): void {
102	    this.config.enabled = enabled;
103	    this.cache.clear();
104	  }
105	
106	  /** Returns read-only view of redactor configuration. */
107	  public getConfig(): Readonly<RedactorConfig> {
108	    return this.config;
109	  }
110	
111	  /** Returns all registered rules (both native model labels and overlay rules). */
112	  public getRules(): PiiRule[] {
113	    return Array.from(this.rules.values());
114	  }
115	
116	  /**
117	   * Toggles an individual rule by id (case, format, and alias insensitive).
118	   * Returns the new enabled state, or false if the rule was not found.
119	   */
120	  public toggleRule(ruleId: string, enabled?: boolean): boolean {
121	    const rule =
122	      this.rules.get(ruleId) ??
123	      findRuleByIdOrLabel(this.rules.values(), ruleId);
124	
125	    if (!rule) return false;
126	    rule.enabled = enabled ?? !rule.enabled;
127	    this.cache.clear();
128	    return rule.enabled;
129	  }
