131	  /**
132	   * Returns the initialized NER engine, loading it on demand if necessary.
133	   * Concurrent calls await the same initialization promise.
134	   */
135	  public async getRedactInstance(): Promise<NerEngine> {
136	    if (this.instance) {
137	      return this.instance;
138	    }
139	    if (!this.initPromise) {
140	      this.initPromise = (async () => {
141	        try {
142	          const loadOpts: MaskerLoadOptions = { ...this.loadOptions };
143	          if (this.config.modelDirectory && !loadOpts.directory) {
144	            loadOpts.directory = this.config.modelDirectory;
145	          }
146	          const loaded = await MaskerMini.load(loadOpts);
147	          try {
148	            await loaded.redaction("warm up", { labels: ["GIVEN_NAME"] });
149	          } catch (error) {
150	            loaded.dispose();
151	            throw error;
152	          }
153	          this.instance = loaded;
154	          return loaded;
155	        } catch (error) {
156	          this.initPromise = null;
157	          throw error;
158	        }
159	      })();
160	    }
161	    return this.initPromise;
162	  }
163	
164	  /** Eagerly initializes the model. */
165	  public async init(): Promise<void> {
166	    await this.getRedactInstance();
167	  }
168	
169	  /** Releases model resources. Safe to call multiple times. */
170	  public dispose(): void {
171	    if (this.instance) {
172	      this.instance.dispose();
173	      this.instance = null;
174	    }
175	    this.initPromise = null;
176	    // The vault is intentionally kept: the session still needs it for restore.
177	    this.cache.clear();
178	  }
179	
180	  /** Returns the session vault that owns all token <-> original mappings. */
181	  public getVault(): PiiVault {
182	    return this.vault;
183	  }
184	
185	  /** Replaces the session vault (e.g. one rebuilt from persisted session entries). */
186	  public setVault(vault: PiiVault): void {
187	    this.vault = vault;
188	    this.cache.clear();
189	  }
190	
191	  /**
192	   * Restores vault tokens in text (e.g. an LLM response) back to their original sensitive values.
193	   * Tolerant of dropped brackets, case changes, and inner whitespace.
194	   */
195	  public restore(processed: string, onHit?: (entry: VaultEntry) => void): string {
196	    return this.vault.restore(processed, onHit);
197	  }
198	
199	  /**
200	   * Replaces regex matches in `text` while never touching matches that overlap a vault token.
201	   * `fn` returns the replacement, or null to keep the match unchanged.
202	   */
203	  private replaceOutsideTokens(
204	    text: string,
205	    regex: RegExp,
206	    fn: (match: string, start: number, end: number) => string | null
207	  ): string {
208	    const spans = this.vault.findTokens(text);
209	    let out = "";
210	    let last = 0;
211	    regex.lastIndex = 0;
212	    let m: RegExpExecArray | null;
213	    while ((m = regex.exec(text)) !== null) {
214	      const start = m.index;
215	      const end = start + m[0].length;
216	      if (m[0].length === 0) {
217	        regex.lastIndex++;
218	        continue;
219	      }
220	      if (spans.some((s) => start < s.end && end > s.start)) {
221	        regex.lastIndex = start + 1;
222	        continue;
223	      }
224	      const rep = fn(m[0], start, end);
225	      if (rep === null) continue;
226	      out += text.slice(last, start) + rep;
227	      last = end;
228	    }
229	    return out + text.slice(last);
230	  }
231	
232	  private cacheSignature(): string {
233	    return `${this.config.minimumConfidence ?? ""}|${this.config.modelDirectory ?? ""}`;
234	  }
235	
236	  private cacheGet(text: string): CachedResult | undefined {
237	    if (this.cacheSig !== this.cacheSignature()) {
238	      this.cache.clear();
239	      return undefined;
240	    }
241	    const hit = this.cache.get(text);
242	    if (hit) {
243	      this.cache.delete(text);
244	      this.cache.set(text, hit); // refresh LRU position
245	    }
246	    return hit;
247	  }
248	
249	  private cacheSet(text: string, value: CachedResult): void {
250	    this.cacheSig = this.cacheSignature();
251	    this.cache.set(text, value);
252	    if (this.cache.size > RESULT_CACHE_LIMIT) {
253	      const oldest = this.cache.keys().next().value;
254	      if (oldest !== undefined) this.cache.delete(oldest);
255	    }
256	  }
257	
258	  private buildResult(text: string, redactions: RedactionDetail[]): RedactionResult {
259	    return {
260	      text,
261	      hasRedactions: redactions.length > 0,
262	      count: redactions.length,
263	      redactions,
264	      restore: (p: string) => this.vault.restore(p),
265	    };
266	  }
267	
268	  /**
269	   * Asynchronously redacts sensitive data (PII and API secrets) from the input text.
270	   * Originals are mapped to stable session-wide vault tokens, so the same value always
271	   * receives the same token across calls.
272	   */
273	  public async redact(text: string): Promise<RedactionResult> {
274	    if (!this.config.enabled || !text || typeof text !== "string") {
275	      return {
276	        text: text ?? "",
277	        hasRedactions: false,
278	        count: 0,
279	        redactions: [],
280	        restore: (p: string) => p ?? "",
281	      };
282	    }
283	
284	    const vault = this.vault;
285	    let currentText = text;
286	    const allRedactions: RedactionDetail[] = [];
287	
288	    // 1. Partition active rules into regex overlay rules vs native model labels
289	    const activeRegexRules: PiiRule[] = [];
290	    const activeNativeLabels: string[] = [];
291	    const enabledVaultLabels = new Set<string>();
292	
293	    for (const rule of this.rules.values()) {
294	      if (!rule.enabled) continue;
295	
296	      if (rule.pattern) {
297	        activeRegexRules.push(rule);
298	        if (!rule.mask) enabledVaultLabels.add(this.overlayLabel(rule));
299	      } else {
300	        const label =
301	          rule.nativeLabel ??
302	          RULE_ID_TO_LABEL[rule.id] ??
303	          (rule.id.toUpperCase().replace(/-/g, "_"));
304	        if (label) {
305	          activeNativeLabels.push(label);
306	          enabledVaultLabels.add(label);
307	        }
308	      }
309	    }
310	
311	    // Cache hit: the cached text may predate originals the vault learned since, so re-apply
312	    // the (model-free) fast path before returning it.
313	    const cached = this.cacheGet(text);
314	    if (cached) {
315	      const redactions = cached.redactions.map((r) => ({ ...r }));
316	      const before = redactions.length;
317	      const refreshed = this.applyKnownOriginals(cached.text, enabledVaultLabels, redactions);
318	      if (redactions.length > before) {
319	        this.cacheSet(text, { text: refreshed, redactions: redactions.map((r) => ({ ...r })) });
320	      }
321	      return this.buildResult(refreshed, redactions);
322	    }
323	
324	    // 2. Fast path: replace already-known originals with their tokens (longest first)
325	    currentText = this.applyKnownOriginals(currentText, enabledVaultLabels, allRedactions);
326	
327	    // 3. Overlay regex rules (API keys, IP addresses, emails, custom secrets)
328	    for (const rule of activeRegexRules) {
329	      const flags = rule.pattern!.flags.includes("g")
330	        ? rule.pattern!.flags
331	        : `${rule.pattern!.flags}g`;
332	      const regex = new RegExp(rule.pattern!.source, flags);
333	
334	      const source = currentText;
335	      currentText = this.replaceOutsideTokens(currentText, regex, (match, start, end) => {
336	        if (rule.validate && !rule.validate(match, { text: source, start, end })) return null;
337	        // Rules with a custom mask are one-way and never enter the vault.
338	        const masked = rule.mask
339	          ? rule.mask(match)
340	          : vault.tokenFor(this.overlayLabel(rule), match);
341	        allRedactions.push({
342	          category: rule.category,
343	          ruleId: rule.id,
344	          original: match,
345	          masked,
346	          placeholder: masked,
347	        });
348	        return masked;
349	      });
350	    }
351	
352	    // 4. Model inference for all active model labels in one call.
353	    // CRITICAL: if activeNativeLabels is empty, do not call the model at all (and never pass
354	    // an empty label list to an engine, which could be read as "all labels").
355	    if (activeNativeLabels.length > 0) {
356	      const redactInstance = await this.getRedactInstance();
357	      const source = currentText;
358	      const protectedSpans = vault.findTokens(source);
359	      const result = await redactInstance.redaction(source, {
360	        labels: activeNativeLabels,
361	        minimumConfidence: this.config.minimumConfidence ?? 0.55,
362	      });
363	
364	      // Rebuild the text from item offsets so items overlapping existing tokens are dropped.
365	      let rebuilt = "";
366	      let cursor = 0;
367	      const accepted: Array<{ original: string; token: string }> = [];
368	      const items = [...result.items].sort((a, b) => (a.start ?? 0) - (b.start ?? 0));
369	      for (const item of items) {
370	        if (!item.original) continue;
371	        let start = item.start;
372	        let end = item.end;
373	        if (
374	          typeof start !== "number" ||
375	          typeof end !== "number" ||
376	          source.slice(start, end) !== item.original
377	        ) {
378	          start = source.indexOf(item.original, cursor);
379	          end = start + item.original.length;
380	        }
381	        if (start < cursor) continue; // overlaps a previous item or is unlocatable
382	        if (protectedSpans.some((s) => start < s.end && end > s.start)) continue;
383	
384	        const token = vault.tokenFor(item.label, item.original);
385	        const matchingRule = this.findRuleForNativeLabel(item.label);
386	        rebuilt += source.slice(cursor, start) + token;
387	        cursor = end;
388	        accepted.push({ original: item.original, token });
389	        allRedactions.push({
390	          category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
391	          ruleId: matchingRule?.id ?? item.label.toLowerCase(),
392	          original: item.original,
393	          masked: token,
394	          placeholder: token,
395	          confidence: item.confidence,
396	          start,
397	          end,
398	        });
399	      }
400	      currentText = rebuilt + source.slice(cursor);
401	
402	      // Sanitize repeated discrete occurrences of detected entities with the same token
403	      // (no extra RedactionDetail entries: each occurrence is reported once at detection).
404	      for (const { original, token } of accepted) {
405	        if (original.trim().length <= 1) continue;
406	        currentText = this.replaceOutsideTokens(
407	          currentText,
408	          createEntityWordBoundaryRegex(original),
409	          () => token
410	        );
411	      }
412	    }
413	
414	    this.cacheSet(text, {
415	      text: currentText,
416	      redactions: allRedactions.map((r) => ({ ...r })),
417	    });
418	    return this.buildResult(currentText, allRedactions);
419	  }
420	
421	  /** Replaces already-known vault originals (for enabled labels) with their tokens, longest first. */
422	  private applyKnownOriginals(
423	    text: string,
424	    enabledVaultLabels: ReadonlySet<string>,
425	    redactions: RedactionDetail[]
426	  ): string {
427	    let currentText = text;
428	    for (const entry of this.vault.knownOriginals()) {
429	      if (!enabledVaultLabels.has(entry.label)) continue;
430	      if (entry.original.trim().length <= 1 || !currentText.includes(entry.original)) continue;
431	      const rule = this.findRuleForNativeLabel(entry.label);
432	      currentText = this.replaceOutsideTokens(
433	        currentText,
434	        createEntityWordBoundaryRegex(entry.original),
435	        () => {
436	          redactions.push({
437	            category: rule?.category ?? this.mapNativeLabelToCategory(entry.label),
438	            ruleId: rule?.id ?? entry.label.toLowerCase(),
439	            original: entry.original,
440	            masked: entry.token,
441	            placeholder: entry.token,
442	          });
443	          return entry.token;
444	        }
445	      );
446	    }
447	    return currentText;
448	  }
449	
450	  private overlayLabel(rule: PiiRule): string {
451	    return (
452	      rule.nativeLabel ??
453	      (rule.category === "api-key"
454	        ? "API_KEY"
455	        : rule.category.toUpperCase().replace(/[-\s]/g, "_"))
456	    );
457	  }
458	
459	  private findRuleForNativeLabel(label: string): PiiRule | undefined {
460	    return findRuleByIdOrLabel(this.rules.values(), label);
461	  }
462	
463	  private mapNativeLabelToCategory(label: string): PiiCategory {
464	    const upper = label.toUpperCase();
465	    switch (upper) {
466	      case "EMAIL":
467	        return "email";
468	      case "PHONE":
469	        return "phone";
470	      case "IP_ADDRESS":
471	        return "ip";
472	      case "CREDIT_CARD":
473	        return "credit-card";
474	      default:
475	        return upper as PiiCategory;
476	    }
477	  }
478	}
