199	  /**
200	   * Replaces regex matches in `text` while never touching matches that overlap a vault token.
201	   * `fn` returns the replacement, or null to keep the match unchanged.
202	   */
203	  private replaceOutsideTokens(
204	    text: string,
205	    regex: RegExp,
206	    fn: (match: string, start: number, end: number) => string | null
207	  ): string {
208	    const spans = this.vault.findTokens(text);
209	    let out = "";
210	    let last = 0;
211	    regex.lastIndex = 0;
212	    let m: RegExpExecArray | null;
213	    while ((m = regex.exec(text)) !== null) {
214	      const start = m.index;
215	      const end = start + m[0].length;
216	      if (m[0].length === 0) {
217	        regex.lastIndex++;
218	        continue;
219	      }
220	      if (spans.some((s) => start < s.end && end > s.start)) {
221	        regex.lastIndex = start + 1;
222	        continue;
223	      }
224	      const rep = fn(m[0], start, end);
225	      if (rep === null) continue;
226	      out += text.slice(last, start) + rep;
227	      last = end;
228	    }
229	    return out + text.slice(last);
230	  }
