273	  public async redact(text: string): Promise<RedactionResult> {
274	    if (!this.config.enabled || !text || typeof text !== "string") {
275	      return {
276	        text: text ?? "",
277	        hasRedactions: false,
278	        count: 0,
279	        redactions: [],
