331	        : `${rule.pattern!.flags}g`;
332	      const regex = new RegExp(rule.pattern!.source, flags);
333	
334	      const source = currentText;
335	      currentText = this.replaceOutsideTokens(currentText, regex, (match, start, end) => {
336	        if (rule.validate && !rule.validate(match, { text: source, start, end })) return null;
337	        // Rules with a custom mask are one-way and never enter the vault.
338	        const masked = rule.mask
