340	          : vault.tokenFor(this.overlayLabel(rule), match);
341	        allRedactions.push({
342	          category: rule.category,
343	          ruleId: rule.id,
344	          original: match,
345	          masked,
346	          placeholder: masked,
347	        });
348	        return masked;
349	      });
350	    }
351	
352	    // 4. Model inference for all active model labels in one call.
353	    // CRITICAL: if activeNativeLabels is empty, do not call the model at all (and never pass
354	    // an empty label list to an engine, which could be read as "all labels").
355	    if (activeNativeLabels.length > 0) {
356	      const redactInstance = await this.getRedactInstance();
357	      const source = currentText;
358	      const protectedSpans = vault.findTokens(source);
359	      const result = await redactInstance.redaction(source, {
360	        labels: activeNativeLabels,
