378	          start = source.indexOf(item.original, cursor);
379	          end = start + item.original.length;
380	        }
381	        if (start < cursor) continue; // overlaps a previous item or is unlocatable
382	        if (protectedSpans.some((s) => start < s.end && end > s.start)) continue;
383	
384	        const token = vault.tokenFor(item.label, item.original);
385	        const matchingRule = this.findRuleForNativeLabel(item.label);
386	        rebuilt += source.slice(cursor, start) + token;
387	        cursor = end;
388	        accepted.push({ original: item.original, token });
389	        allRedactions.push({
390	          category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
391	          ruleId: matchingRule?.id ?? item.label.toLowerCase(),
392	          original: item.original,
393	          masked: token,
394	          placeholder: token,
395	          confidence: item.confidence,
396	          start,
397	          end,
398	        });
399	      }
400	      currentText = rebuilt + source.slice(cursor);
