402	      // Sanitize repeated discrete occurrences of detected entities with the same token
403	      // (no extra RedactionDetail entries: each occurrence is reported once at detection).
404	      for (const { original, token } of accepted) {
405	        if (original.trim().length <= 1) continue;
406	        currentText = this.replaceOutsideTokens(
407	          currentText,
408	          createEntityWordBoundaryRegex(original),
409	          () => token
410	        );
411	      }
412	    }
413	
414	    this.cacheSet(text, {
415	      text: currentText,
416	      redactions: allRedactions.map((r) => ({ ...r })),
417	    });
