421	  /** Replaces already-known vault originals (for enabled labels) with their tokens, longest first. */
422	  private applyKnownOriginals(
423	    text: string,
424	    enabledVaultLabels: ReadonlySet<string>,
425	    redactions: RedactionDetail[]
426	  ): string {
427	    let currentText = text;
428	    for (const entry of this.vault.knownOriginals()) {
429	      if (!enabledVaultLabels.has(entry.label)) continue;
430	      if (entry.original.trim().length <= 1 || !currentText.includes(entry.original)) continue;
431	      const rule = this.findRuleForNativeLabel(entry.label);
432	      currentText = this.replaceOutsideTokens(
433	        currentText,
434	        createEntityWordBoundaryRegex(entry.original),
435	        () => {
436	          redactions.push({
437	            category: rule?.category ?? this.mapNativeLabelToCategory(entry.label),
438	            ruleId: rule?.id ?? entry.label.toLowerCase(),
439	            original: entry.original,
440	            masked: entry.token,
441	            placeholder: entry.token,
442	          });
443	          return entry.token;
444	        }
445	      );
446	    }
447	    return currentText;
448	  }
