450	  private overlayLabel(rule: PiiRule): string {
451	    return (
452	      rule.nativeLabel ??
453	      (rule.category === "api-key"
454	        ? "API_KEY"
455	        : rule.category.toUpperCase().replace(/[-\s]/g, "_"))
