463	  private mapNativeLabelToCategory(label: string): PiiCategory {
464	    const upper = label.toUpperCase();
465	    switch (upper) {
466	      case "EMAIL":
467	        return "email";
468	      case "PHONE":
469	        return "phone";
470	      case "IP_ADDRESS":
471	        return "ip";
472	      case "CREDIT_CARD":
473	        return "credit-card";
474	      default:
475	        return upper as PiiCategory;
476	    }
