    const spans = await scanSecrets(text);
    expect(spans).toHaveLength(1);
    expect(spans[0]).toMatchObject({ ruleId: "specific", confidence: "high" });
    expect(text.slice(spans[0].start, spans[0].end)).toBe(secret);
