const n=require("/tmp/eval-secrets.json"), o=require("/tmp/eval-final2.json");
const arr=r=>{const a=r.cases||r.results||r;return Array.isArray(a)?a:Object.values(a)};
const om=new Map(arr(o).map(c=>[c.id,c]));
for(const c of arr(n)){const p=om.get(c.id); const st=x=>x.pii.map(q=>q.status).join(","); if(st(c)!==st(p)||c.redactions.some(r=>r.ruleId=="secrets")){console.log(c.id,"old",st(p),"new",st(c));console.log(" in :",JSON.stringify(c.text.slice(0,160)));console.log(" out:",JSON.stringify(c.output.slice(0,160)));console.log(" sec:",c.redactions.filter(r=>r.ruleId=="secrets").map(r=>r.original.slice(0,40)));}}
const med=a=>a.sort((x,y)=>x-y)[a.length>>1]; console.log("median ms new", med(arr(n).map(c=>c.ms)), "old", med(arr(o).map(c=>c.ms)));
'

