cat > /tmp/cmp.cjs <<'EOF'
const n=require("/tmp/eval-secrets.json"), o=require("/tmp/eval-final2.json");
const arr=r=>{const a=r.cases||r.results||r;return Array.isArray(a)?a:Object.values(a)};
const om=new Map(arr(o).map(c=>[c.id,c]));
